  FDSE idle_r_reg
       (.C(GEN_SCP_reg_0),
        .CE(E),
        .D(next_idle_c),
        .Q(idle_r),
        .S(p_0_in));
  FDRE sof_to_data_r_reg
       (.C(GEN_SCP_reg_0),
        .CE(E),
        .D(next_sof_to_data_c),
        .Q(sof_to_data_r),
